INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29437$nota-0236$m29437$, $m29438$Exercise Physiology McArdle.pdf$m29438$, $m29439$65$m29439$, $m29440$Measuring serum ferritin concentration provides useful information about iron reserves. Values below 20 mg·L−1 for females and 30 mg·L−1 for males indicate depleted reserves.$m29440$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29441$nota-0236$m29441$, $m29442$Exercise Physiology McArdle.pdf$m29442$, $m29443$65$m29443$, $m29444$Several days of training increase plasma volume by 20%, while total red blood cell volume remains unchanged. Consequently, total hemoglobin, an important factor in endurance performance, remains the same or increases slightly with training, while hemoglobin concentration decreases in the expanding plasma volume. Despite this hemoglobin dilution, aerobic capacity and exercise performance improve with training.$m29444$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29445$nota-0236$m29445$, $m29446$Exercise Physiology McArdle.pdf$m29446$, $m29447$67$m29447$, $m29448$iron-depleted but nonanemic women received either a placebo or 20 mg of elemental iron as ferrous sulfate twice daily for 6 wk... The improvement in 15-km endurance cycling time in the supplemented group was twice that of women who consumed the placebo (3.4 vs. 1.6 min faster).$m29448$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29449$nota-0237$m29449$, $m29450$Exercise Physiology McArdle.pdf$m29450$, $m29451$58$m29451$, $m29452$Adolescent girls should consume 1500 mg of calcium daily. Increasing daily calcium intake for middle-aged women, particularly estrogen-deprived women following menopause, from 1200 to 1500 mg improves the body's calcium balance.$m29452$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29453$nota-0237$m29453$, $m29454$Exercise Physiology McArdle.pdf$m29454$, $m29455$58$m29455$, $m29456$One of two women and one of eight men over age 50 can expect an osteoporosis-related fracture in their lifetime... Between 60 and 80% of an individual's susceptibility to osteoporosis links to genetic factors, while 20 to 40% remains lifestyle related.$m29456$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29457$nota-0237$m29457$, $m29458$Exercise Physiology McArdle.pdf$m29458$, $m29459$59$m29459$, $m29460$National Academy of Sciences Recommended Daily Calcium Intake — Adults 19-50 y: 1000 mg; Adult women 51-70 y: 1200 mg; Adults 71 y and older: 1200 mg.$m29460$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29461$nota-0238$m29461$, $m29462$Exercise Physiology McArdle.pdf$m29462$, $m29463$50$m29463$, $m29464$antioxidant supplementation with vitamins C and E to individuals with no previous deficiencies in these vitamins had no effect on physical adaptations to strenuous endurance training.$m29464$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29465$nota-0238$m29465$, $m29466$Exercise Physiology McArdle.pdf$m29466$, $m29467$51$m29467$, $m29468$More than 55 years of research on healthy persons with nutritionally adequate diets does not provide evidence that consuming vitamin (and mineral) supplements improves exercise performance, the hormonal and metabolic responses to exercise, or ability to train arduously and recover from such training.$m29468$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29469$nota-0238$m29469$, $m29470$Exercise Physiology McArdle.pdf$m29470$, $m29471$50$m29471$, $m29472$the natural antioxidant defenses in well-nourished humans respond adequately to increased physical activity... Improvement occurs as the natural enzymatic defenses (superoxide dismutase and glutathione peroxidase) 'up-regulate' through exercise training adaptations.$m29472$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29473$nota-0238$m29473$, $m29474$nota-0204$m29474$, $m29475$complementa$m29475$, $m29476$nota-0204 lista os suplementos COM evidência robusta para ciclismo (cafeína, creatina, bicarbonato, nitrato, beta-alanina); esta nota complementa explicando por que antioxidantes em altas doses NÃO entram nessa lista, apesar de serem populares$m29476$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29477$nota-0255$m29477$, $m29478$Exercise Physiology McArdle.pdf$m29478$, $m29479$628$m29479$, $m29480$table 25.4 provides the predicted sweating rates for individuals of different body weights running at various speeds in cold/temperate and warm weather conditions.$m29480$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29481$nota-0255$m29481$, $m29482$Exercise Physiology McArdle.pdf$m29482$, $m29483$629$m29483$, $m29484$Predicted Sweating Rates (L·hr-1) for Running at 8.5 to 15.0 km·hr-1 in Cool/Temperate (TDB = 18°C) and Warm (TDB = 28°C) Weather — Body Weight 70 kg, Cool/temperate 10 km/hr: 0.79 L/hr; Warm 10 km/hr: 0.89 L/hr; Cool/temperate 15 km/hr: 1.25 L/hr; Warm 15 km/hr: 1.36 L/hr.$m29484$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29485$nota-0255$m29485$, $m29486$nota-0227$m29486$, $m29487$complementa$m29487$, $m29488$nota-0227 descreve o protocolo de estimar a taxa de sudorese por pesagem pré/pós-exercício; esta nota fornece uma tabela de referência preditiva por peso/velocidade/clima como estimativa a priori, sem precisar pesar o atleta$m29488$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29489$nota-0259$m29489$, $m29490$Exercise Physiology McArdle.pdf$m29490$, $m29491$631$m29491$, $m29492$PRE-ACTIVITY 1. Drink approximately 17 to 20 oz 2 to 3 hr before activity. 2. Consume another 7 to 10 oz after warm-up (10 to 15 min before exercise). DURING ACTIVITY 1. Drink approximately 28 to 40 oz every hour of exercise (7 to 10 oz every 10 to 15 min). 2. Rapidly replace lost fluids (sweat and urine) within 2 hr after activity to enhance recovery by drinking 20 to 24 oz for every pound of body weight lost through sweating.$m29492$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29493$nota-0259$m29493$, $m29494$nota-0227$m29494$, $m29495$complementa$m29495$, $m29496$nota-0227 estabelece a regra geral de repor a 80% da taxa de sudorese; esta nota detalha o protocolo ACSM com volumes e frequência específicos para antes/durante/depois$m29496$)
